import {summarize,filterRows,monthList,sourceStatus} from './model.mjs';
const app=document.querySelector('#app');
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let data;
try{const res=await fetch('./data.json',{cache:'no-store'});if(!res.ok)throw Error();data=await res.json();}catch{app.innerHTML='<h1>Income dashboard</h1><p>The saved report could not be loaded. Reload this page to try again.</p>';throw Error('Snapshot unavailable');}
const months=monthList(data.period_start.slice(0,7),data.period_end.slice(0,7));
const label=m=>new Date(`${m}-15T12:00:00Z`).toLocaleString('en-US',{month:'short',year:'numeric',timeZone:'UTC'});
const state={source:'all',start:months[0],end:months.at(-1),currency:'USD'};
const date=v=>v?new Date(v).toLocaleString('en-US',{dateStyle:'medium',timeStyle:'short',timeZone:'America/Chicago'}):'Not available';
const money=v=>v===null||v===undefined?'Not available':new Intl.NumberFormat('en-US',{style:'currency',currency:state.currency}).format(v/100);
const currencies=[...new Set(data.sources.flatMap(s=>s.rows.map(r=>r.currency)))].sort();
app.outerHTML=`<div class="shell"><aside class="rail"><div class="brand">Q<span style="color:var(--muted)"> / </span><em>Finance</em></div><nav aria-label="Sections"><a href="#overview">Overview</a><a href="#sources">Income sources</a><a href="#monthly">Monthly detail</a><a href="#definitions">About the numbers</a></nav><div class="rail-bottom"><div class="identity"><div class="avatar">QF</div><div>Quentin Flores<br><small>Income dashboard</small></div></div>Private workspace<br>Aggregate records only</div></aside><main><header class="topline" id="overview"><div><div class="eyebrow">Business finance</div><h1>Income overview</h1></div><span class="private">Owner access only</span></header><div class="refresh-line"><span>${esc(data.schedule.label)}</span><span>Updated ${esc(date(data.prepared_at))} CT</span></div><div class="filters"><label>Income source<select id="source"><option value="all">All income sources</option>${data.sources.map(s=>`<option value="${s.id}">${esc(s.name)}</option>`).join('')}</select></label><label>From month<select id="start">${months.map(m=>`<option value="${m}">${label(m)}</option>`).join('')}</select></label><label>Through month<select id="end">${months.map(m=>`<option value="${m}" ${m===state.end?'selected':''}>${label(m)}${m===months.at(-1)?' · to date':''}</option>`).join('')}</select></label>${currencies.length>1?`<label>Currency<select id="currency">${currencies.map(c=>`<option value="${c}" ${c==='USD'?'selected':''}>${c}</option>`).join('')}</select></label>`:''}<button id="ytd">${data.period_end.slice(0,4)} YTD</button></div><div id="results" aria-live="polite"></div><section id="definitions" class="panel"><h2>About the numbers</h2><dl><dt>Money coming in</dt><dd>All included payments plus financing advances. Stripe and PayPal show amounts before their reported fees; Skool shows the net payouts sent to you. BILL uses Paid receipts and Gusto uses completed direct deposits. No sales or business classification is required.</dd><dt>After deductions</dt><dd>Incoming money minus reported payment fees, refunds, disputes and financing repayments, plus related reversals. Skool fees are already reflected in its payouts. This is not profit or a bank balance.</dd><dt>Counted once</dt><dd>Stripe and PayPal transfers to a bank, bank funding, holds and reserve releases are excluded. Skool processes member payments on its own merchant account and sends separate community payouts. BILL voids and unpaid invoices are excluded.</dd><dt>Financing</dt><dd>Advances are included when received. Repayments reduce the after-deductions figure. This report does not estimate an outstanding loan balance.</dd><dt>Daily updates</dt><dd>Stripe and PayPal refresh through reporting access. Skool, BILL and Gusto refresh through signed-in browser reports on this Mac. If access fails, the last successful amounts stay visible and the source is marked stale. The Mac must be available and browser sessions signed in.</dd><dt>Timing and coverage</dt><dd>Months use America/Chicago. Stripe uses balance-entry dates; PayPal uses transaction initiation dates. Skool uses payout dates, BILL uses delivery dates, and Gusto uses paydays. The current month is partial. Provider indexing and bank posting may lag.</dd></dl><details><summary>Source details</summary><p class="section-sub" style="margin-top:16px">${esc(data.basis_note)} General PayPal payment credits are included at your request. BILL’s recorded cash receipt uses the delivery date recorded in BILL. Fee details unavailable from browser payout reports are not invented.</p><p class="section-sub"><a href="https://docs.stripe.com/reports/reporting-categories" target="_blank" rel="noreferrer">Stripe categories</a> · <a href="https://developer.paypal.com/reports/reference/t-codes/" target="_blank" rel="noreferrer">PayPal event codes</a> · <a href="https://help.skool.com/article/86-subscriptions-faq" target="_blank" rel="noreferrer">Skool payment processing</a></p></details></section><footer class="foot"><span>Daily income dashboard · America/Chicago</span><span>No currency conversion · Private reporting</span></footer></main></div>`;
for(const key of ['source','start','end','currency'])document.getElementById(key)?.addEventListener('change',e=>{state[key]=e.target.value;if(state.start>state.end){if(key==='start')state.end=state.start;else state.start=state.end;document.getElementById('start').value=state.start;document.getElementById('end').value=state.end;}render();});
document.getElementById('ytd').addEventListener('click',()=>{state.start=months[0];state.end=months.at(-1);document.getElementById('start').value=state.start;document.getElementById('end').value=state.end;render();});
const bridgeRow=(name,value,cls='')=>`<div class="bridge-row ${cls}"><span>${name}</span><span>${value}</span></div>`;
function render(){
 const selected=data.sources.filter(s=>state.source==='all'||s.id===state.source);
 const pick=s=>filterRows(s.rows,state.start+'-01',state.end+'-31',state.currency);
 const activeRows=selected.flatMap(pick),r=summarize(activeRows);
 const stale=selected.filter(s=>sourceStatus(s)==='stale');
 const title=state.source==='all'?'All income sources':selected[0].name;
 const monthRows=monthList(state.start,state.end).map(month=>({month,metrics:summarize(activeRows.filter(x=>x.month===month))}));
 const max=Math.max(1,...monthRows.map(x=>Math.max(x.metrics.incoming,x.metrics.net)));
 const chart=`<div class="chart" role="img" aria-label="Monthly incoming money and amount after known deductions; exact values in the monthly detail table">${monthRows.map(({month,metrics:x})=>`<div class="bar-group"><div class="bars"><div class="bar" style="height:${Math.max(0,x.incoming)/max*100}%" title="${label(month)} incoming ${money(x.incoming)}"></div><div class="bar net" style="height:${Math.max(0,x.net)/max*100}%" title="${label(month)} after deductions ${money(x.net)}"></div></div><div class="month">${label(month).slice(0,3)}${month===months.at(-1)?'*':''}</div></div>`).join('')}</div><p class="chart-note">* Current month through the source cutoffs below. Negative values appear in the table.</p>`;
 const table=`<div class="table-wrap"><table><thead><tr><th>Month</th><th>Money in</th><th>Financing included</th><th>Fees & adjustments</th><th>Repayments</th><th>After deductions</th></tr></thead><tbody>${monthRows.map(({month,metrics:x})=>`<tr><td>${label(month)}${month===months.at(-1)?' <small>partial</small>':''}</td><td>${money(x.incoming)}</td><td>${money(x.financing)}</td><td>${money(x.fees+x.adjustments)}</td><td>${money(x.repayments)}</td><td>${money(x.net)}</td></tr>`).join('')}</tbody><tfoot><tr><td>Selected period</td><td>${money(r.incoming)}</td><td>${money(r.financing)}</td><td>${money(r.fees+r.adjustments)}</td><td>${money(r.repayments)}</td><td>${money(r.net)}</td></tr></tfoot></table></div>`;
 const sourceCards=data.sources.map(s=>{const x=summarize(pick(s));const current=sourceStatus(s)==='current';return `<article class="source card"><div class="source-head"><h3>${esc(s.name)}</h3><span class="pill ${current?'verified':''}">${current?'Updated':'Stale'}</span></div><div class="source-number">${money(x.incoming)}</div><p>${esc(s.note)}</p><small>${esc(s.account)}</small><small>${x.count.toLocaleString()} incoming records · ${esc(s.mode)}</small><small>Checked ${esc(date(s.checked_at))} CT${s.indexed_through?'<br>Indexed through '+esc(date(s.indexed_through))+' CT':''}</small>${s.issue?`<small class="warning">${esc(s.issue)}</small>`:''}${s.groups.length?`<div class="source-stats">${s.groups.map(g=>bridgeRow(esc(g),money(summarize(pick(s).filter(b=>b.group===g)).incoming))).join('')}</div>`:''}</article>`;}).join('');
 const latest=activeRows.filter(b=>['income','financing'].includes(b.kind)).toSorted((a,b)=>b.date.localeCompare(a.date)).slice(0,12);
 document.getElementById('results').innerHTML=`${stale.length?`<div class="coverage"><strong>${stale.map(s=>esc(s.name)).join(', ')} needs a refresh.</strong> Last successful amounts are included; newer income may be missing.</div>`:''}<section class="metrics"><div class="card primary"><div class="metric-label">Money coming in · ${state.currency}</div><div class="number">${money(r.incoming)}</div><small>${esc(title)} · includes financing</small></div><div class="card"><div class="metric-label">After known deductions · ${state.currency}</div><div class="number">${money(r.net)}</div><small>After payment deductions and financing repayments</small></div><div class="card"><div class="metric-label">Financing received · ${state.currency}</div><div class="number">${money(r.financing)}</div><small>Included in money coming in<br>${money(r.repayments)} repaid in this period</small></div></section><div class="grid"><section class="panel"><div class="panel-head"><h2>Monthly income</h2><div class="legend"><span>Money in</span><span>After deductions</span></div></div>${chart}</section><section class="panel"><div class="panel-head"><h2>What remains</h2><span class="tag">Selected period</span></div>${bridgeRow('Payments received',money(r.income))}${bridgeRow('Financing received','+'+money(r.financing))}${bridgeRow('Payment fees','−'+money(r.fees))}${bridgeRow('Other fees, refunds & disputes, net','−'+money(r.adjustments))}${bridgeRow('Financing repayments','−'+money(r.repayments))}${bridgeRow('After known deductions',money(r.net),'total')}</section></div><section id="sources"><h2 class="section-title">Income sources</h2><p class="section-sub">Amounts for the selected months. Each source shows its own last successful update.</p><div class="source-grid">${sourceCards}</div></section><section class="panel" id="monthly"><div class="panel-head"><div><h2>Monthly detail</h2><small>${esc(title)}</small></div><small>${label(state.start)} – ${label(state.end)} · ${state.currency}</small></div>${table}</section><section class="panel" style="margin:22px 0"><div class="panel-head"><h2>Recent incoming activity</h2><small>Daily totals by source</small></div><div class="table-wrap"><table><thead><tr><th>Date</th><th>Source</th><th>Payments</th><th>Money in</th></tr></thead><tbody>${latest.map(b=>`<tr><td>${esc(b.date)}</td><td>${esc(data.sources.find(s=>s.id===b.source).name)}${b.group?' · '+esc(b.group):''}${b.kind==='financing'?' · Financing':''}</td><td>${b.count}</td><td>${money(b.amount_minor)}</td></tr>`).join('')||'<tr><td colspan="4">No incoming records in this period.</td></tr>'}</tbody></table></div></section><section class="panel" style="margin-bottom:22px"><details style="margin:0;border:0;padding:0"><summary>Coverage and excluded movements</summary>${selected.map(s=>`<p class="section-sub" style="margin-top:14px"><strong>${esc(s.name)}:</strong> ${esc(s.coverage)} Checked ${esc(date(s.checked_at))} CT.</p>`).join('')}<p class="section-sub">Bank payouts, funding, holds, reserves, voids and unsupported movements are retained for review but do not increase money coming in. ${r.review?`${money(r.review)} of positive movements is outside the total for source/status review.`:''}</p><div class="table-wrap"><table><thead><tr><th>Source</th><th>Movement</th><th>Signed amount</th><th>Status</th></tr></thead><tbody>${aggregateExcluded(activeRows).map(b=>`<tr><td>${esc(b.source)}</td><td>${esc(b.category.replaceAll('_',' '))}</td><td>${money(b.amount_minor)}</td><td>${esc(b.kind)}</td></tr>`).join('')||'<tr><td colspan="4">No excluded movements in this selection.</td></tr>'}</tbody></table></div></details></section>`;
}
function aggregateExcluded(rows){const map=new Map();for(const b of rows.filter(x=>['review','excluded'].includes(x.kind))){const key=[b.source,b.category,b.kind].join('|');if(!map.has(key))map.set(key,{...b,amount_minor:0});map.get(key).amount_minor+=b.amount_minor;}return [...map.values()];}
render();
// Automatically pick up a newly published daily snapshot while this tab stays open.
async function checkUpdate(){if(document.hidden)return;try{const res=await fetch('./data.json',{cache:'no-store'});if(!res.ok)return;const next=await res.json();if(next.prepared_at!==data.prepared_at)location.reload();else render();}catch{}}
setInterval(checkUpdate,300000);document.addEventListener('visibilitychange',checkUpdate);
